int main()
{
    CArray<CEngineScene*> scenes;
    g_test_resource = CShaderResourceTestFactory::Create();
    g_test_data = CVertexShaderDataTestFactory::Create();
    g_test_resource_manager.ShaderResourceAt2A28 = g_test_resource;
    {
        CEnginePrimitiveManagerWeaponTrails manager(scenes);
        check(g_base_class_ctor_calls == 1 && g_noncopy_ctor_calls == 1 &&
            g_render_util_ctor_calls == 1 && g_base_ctor_calls == 1,
            "complete RTTI base chain constructed once");
        check(g_lifecycle_count == 4 && g_lifecycle[0] == 1 &&
            g_lifecycle[1] == 2 && g_lifecycle[2] == 3 && g_lifecycle[3] == 4,
            "base-to-derived construction order");
        check(manager.Scenes == &scenes && manager.Enable, "base manager state");
        check(g_enable_hook_calls == 1, "enable hook call count");
        check(g_enable_name && std::strcmp(g_enable_name, "EnableWeaponTrails") == 0,
            "enable variable literal");
        check(g_tree_initialise_calls == 1 && g_initialise_arg == 3,
            "tree filer Initialize(3)");
        check(manager.VertexBufferPool.AllocCount == 0 &&
            manager.VertexBufferPool.FreePoolMem == 0 &&
            manager.VertexBufferPool.TotalMemAllocated == 0,
            "pool counters zeroed");
        check(manager.VertexBufferPool.ResourceMappingTree.BaseNode == &g_test_tree_node &&
            manager.VertexBufferPool.ResourceMappingTree.KeySize == 3,
            "native tree state initialized");
        check(manager.VertexBufferPool.NativeVptr ==
            static_cast<void*>(CEngineVertexBufferPoolNativeVTable),
            "pool final native vptr");
        check(manager.VertexBufferPool.SizeGranularity == 0x400,
            "pool size granularity");
        check(g_get_vertex_shader_calls == 1 && g_shader_name &&
            std::strcmp(g_shader_name, "VSHADER_TRANSFORM_COL_TEX0") == 0,
            "vertex shader lookup");
        check(manager.VertexShaderZSortedUnlit.Data == g_test_data &&
            g_test_data->ReferenceCount == 1 && manager.VertexShaderZSortedUnlit.CountReferences() == 1,
            "temporary shader assignment retains one reference");

        CEnginePrimitiveManager* virtualBase = &manager;
        CEngineInternalPrimitiveBase primitive;
        CEngineSubPrimitiveBase subprimitive;
        CEngineSubPrimitiveChain chain;
        CEnginePrimitiveTypeList types;
        check(virtualBase->CreateInternalPrimitive(EEnginePrimitiveTypeNativeView) == 0,
            "derived slot 1");
        virtualBase->GetSupportedTypes(types);
        virtualBase->RenderSubPrimitive(subprimitive, ERenderPassTypeNativeView);
        check(virtualBase->RenderPrimitive(primitive, EEngineRenderLayerNativeView, chain) ==
            ERenderedNativeView, "derived slot 7");
        check(g_virtual_calls == 4, "native virtual override dispatch");
    }
    check(g_manager_dtor_calls == 1 && g_render_util_dtor_calls == 1 &&
        g_noncopy_dtor_calls == 1 && g_base_class_dtor_calls == 1,
        "complete RTTI base chain destroyed once");
    check(g_lifecycle_count == 8 && g_lifecycle[4] == 5 &&
        g_lifecycle[5] == 6 && g_lifecycle[6] == 7 && g_lifecycle[7] == 8,
        "derived-to-base destruction order");
    check(g_test_data->ReferenceCount == 0 && g_data_destructor_calls == 1,
        "shader temporary and manager cleanup balance references");
    CShaderResourceTestFactory::Destroy(g_test_resource);
    if (g_failures == 0) {
        std::puts("00bcc5f0_TEST PASS");
        return 0;
    }
    std::printf("00bcc5f0_TEST FAIL count=%d\n", g_failures);
    return 1;
}
